class MyCounter extends HTMLElement {
  constructor() {
    super();
    this.count = 0;
    this.attachShadow({ mode: "open" });
    this.shadowRoot.innerHTML = `
      <style>button { font-size: 1.2em; }</style>
      <button>Count: 0</button>
    `;
    this.shadowRoot.querySelector("button")
      .addEventListener("click", () => this.increment());
  }

  increment() {
    this.count++;
    this.shadowRoot.querySelector("button")
      .textContent = `Count: ${this.count}`;
  }

  connectedCallback() {
    console.log("Counter added to page");
  }

  disconnectedCallback() {
    console.log("Counter removed from page");
  }
}

customElements.define("my-counter", MyCounter);

class MyCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this.shadowRoot.innerHTML = `
      <style>
        /* This CSS only affects THIS component! */
        .card { border: 1px solid #ccc; padding: 16px; border-radius: 8px; }
        .card h2 { color: navy; margin: 0; }
      </style>
      <div class="card">
        <h2><slot name="title"></slot></h2>
        <p><slot></slot></p>
      </div>
    `;
  }
}

customElements.define("my-card", MyCard);

